var levels = new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().Select(l => new { l.Name, id = l.Id.IntegerValue, elevM = Math.Round(l.Elevation*0.3048,3) }).ToList();
var wallTypes = new FilteredElementCollector(doc).OfClass(typeof(WallType)).Cast<WallType>().Select(w => new { w.Name, id = w.Id.IntegerValue, kind = w.Kind.ToString(), widthMm = Math.Round(w.Width*304.8) }).ToList();
var roofTypes = new FilteredElementCollector(doc).OfClass(typeof(RoofType)).Select(r => new { r.Name, id = r.Id.IntegerValue }).ToList();
var floorTypes = new FilteredElementCollector(doc).OfClass(typeof(FloorType)).Select(r => new { r.Name, id = r.Id.IntegerValue }).ToList();
Func<BuiltInCategory, object> syms = c => new FilteredElementCollector(doc).OfCategory(c).OfClass(typeof(FamilySymbol)).Cast<FamilySymbol>().Select(s => new { fam = s.FamilyName, s.Name, id = s.Id.IntegerValue }).ToList();
var rtypes = new FilteredElementCollector(doc).OfClass(typeof(ElementType)).Where(e=>e.Category!=null && e.Category.Id.IntegerValue==(int)BuiltInCategory.OST_RoomTags).Count();
return new { levels, wallTypes, roofTypes, floorTypes, doors = syms(BuiltInCategory.OST_Doors), windows = syms(BuiltInCategory.OST_Windows), plumbing = syms(BuiltInCategory.OST_PlumbingFixtures), roomTagTypes = rtypes };
